import os, csv, json, numpy as np
try:
    from scipy.optimize import linear_sum_assignment
except Exception:
    linear_sum_assignment = None

N = 26
TOL = 1e-8

D_EXP = 'storage/noesis/exports/exp284'
D_NOE = 'storage/noesis/exports/sota_243'
D_SCI_CAND = [
    'storage/Scientia/nmap/n26',
    '/home/ubuntu/station_2/station_data/rooms/research/storage/lineages/scientia/nmap/n26',
]

OUT_DIR = 'storage/noesis/nmap'
OUT_JSON = os.path.join(OUT_DIR, 'triad_jaccard_v4_exp284_noesis243_scientia259_tol1e8.json')
OUT_CSV  = os.path.join(OUT_DIR, 'triad_jaccard_v4_exp284_noesis243_scientia259_tol1e8.csv')

CANON = {
  'xl':'xL','left':'xL','l':'xL','x_left':'xL',
  'xr':'xR','right':'xR','r':'xR','x_right':'xR',
  'yb':'yB','bottom':'yB','b':'yB','y_bottom':'yB',
  'yt':'yT','top':'yT','t':'yT','y_top':'yT',
  'xl.':'xL','xr.':'xR','yb.':'yB','yt.':'yT',
  'xL':'xL','xR':'xR','yB':'yB','yT':'yT'
}

def first_existing(paths):
    for p in paths:
        if isinstance(p, (list, tuple)):
            p = os.path.join(*p)
        if os.path.exists(p):
            return p
    return None

def read_pairs_raw(path):
    rows=[]
    with open(path,'r') as f:
        for ln in f:
            toks=[t for t in ln.replace(',', ' ').split() if t]
            if len(toks)<2: continue
            try:
                i=int(float(toks[0])); j=int(float(toks[1]))
            except:
                continue
            rows.append((i,j))
    return rows

def read_bound_raw(path):
    rows=[]
    with open(path,'r') as f:
        for ln in f:
            toks=[t for t in ln.replace(',', ' ').split() if t]
            if len(toks)<2: continue
            try:
                i=int(float(toks[0]))
            except:
                continue
            side_raw = toks[1].strip()
            side = CANON.get(side_raw.lower(), side_raw)
            side2 = CANON.get(side.lower().strip(' :;,'), side)
            if side2 in ('xL','xR','yB','yT'):
                rows.append((i, side2))
    return rows

def normalize_indices(rows, kind):
    # kind: 'pairs' or 'bound'
    # Decide 0-based (0..N-1) vs 1-based (1..N)
    if kind=='pairs':
        idxs = [i for (i,_) in rows] + [j for (_,j) in rows]
    else:
        idxs = [i for (i,_) in rows]
    if not idxs:
        return set(), {'applied': False, 'mode': 'empty'}

    c0 = sum(0 <= v <= N-1 for v in idxs)
    c1 = sum(1 <= v <= N     for v in idxs)
    meta = {'applied': False, 'mode': 'as-is'}

    out=set()
    if c1 > c0 and all(1 <= v <= N for v in idxs):
        # Likely 1-based: shift down by 1
        meta = {'applied': True, 'mode': 'minus_one'}
        if kind=='pairs':
            for (i,j) in rows:
                a,b = i-1, j-1
                if 0 <= a < N and 0 <= b < N and a!=b:
                    u,v = (a,b) if a<b else (b,a)
                    out.add((u,v))
        else:
            for (i,s) in rows:
                a = i-1
                if 0 <= a < N:
                    out.add((a,s))
    else:
        # Assume 0-based
        if kind=='pairs':
            for (i,j) in rows:
                if 0 <= i < N and 0 <= j < N and i!=j:
                    u,v = (i,j) if i<j else (j,i)
                    out.add((u,v))
        else:
            for (i,s) in rows:
                if 0 <= i < N:
                    out.add((i,s))
    return out, meta

def read_centers(path):
    rows=[]
    with open(path,'r') as f:
        for ln in f:
            toks=[t for t in ln.split() if t]
            if len(toks)>=2:
                rows.append([float(toks[0]), float(toks[1])])
    C=np.array(rows, float)
    if C.shape!=(N,2): raise ValueError(f"centers shape mismatch: {path} got {C.shape}")
    return C

def jaccard(A,B):
    I=A & B; U=A | B
    J=float(len(I))/float(len(U)) if len(U)>0 else 1.0
    return J, len(I), len(U), len(U)-len(I)

def align_map(CA, CB):
    M=np.sum((CA[:,None,:]-CB[None,:,:])**2, axis=2)
    if linear_sum_assignment is None:
        a_idx=np.lexsort((CA[:,1], CA[:,0]))
        b_idx=np.lexsort((CB[:,1], CB[:,0]))
        P=np.zeros(N, dtype=int); P[a_idx]=b_idx
        return P
    r,c=linear_sum_assignment(M)
    P=np.zeros(N, dtype=int); P[r]=c
    return P

def map_pairs(P, S):
    T=set()
    for (i,j) in S:
        if 0<=i<N and 0<=j<N:
            a=int(P[i]); b=int(P[j])
            if a==b: continue
            u,v=(a,b) if a<b else (b,a)
            T.add((u,v))
    return T

def map_bound(P, S):
    T=set()
    for (i,side) in S:
        if 0<=i<N:
            T.add((int(P[i]), side))
    return T

def load_pack(dir_pairs, dir_bound, centers_path=None):
    pr_raw = read_pairs_raw(os.path.join(dir_pairs, 'active_pairs_tol1e8.csv'))
    bd_raw = read_bound_raw(os.path.join(dir_bound, 'active_boundary_tol1e8.csv'))
    pairs, m_pairs = normalize_indices(pr_raw, 'pairs')
    bound, m_bound = normalize_indices(bd_raw, 'bound')
    C = read_centers(centers_path) if centers_path else None
    return {'pairs': pairs, 'bound': bound, 'centers': C,
            'meta': {'pairs_norm': m_pairs, 'bound_norm': m_bound}}

def comp_pair(A, B, do_align=True):
    C = {'meta': {'A_norm': A['meta'], 'B_norm': B['meta']}}
    jb, ib, ub, db = jaccard(A['bound'], B['bound'])
    jp, ip, up, dp = jaccard(A['pairs'], B['pairs'])
    C['unaligned'] = {'boundary': {'J': jb, 'I': ib, 'U': ub, 'D': db},
                      'pairs':    {'J': jp, 'I': ip, 'U': up, 'D': dp}}
    if do_align and A.get('centers') is not None and B.get('centers') is not None:
        P = align_map(A['centers'], B['centers'])
        Ab = map_bound(P, A['bound']); Ap = map_pairs(P, A['pairs'])
        jb2, ib2, ub2, db2 = jaccard(Ab, B['bound'])
        jp2, ip2, up2, dp2 = jaccard(Ap, B['pairs'])
        C['aligned_A_to_B'] = {'boundary': {'J': jb2, 'I': ib2, 'U': ub2, 'D': db2},
                               'pairs':    {'J': jp2, 'I': ip2, 'U': up2, 'D': dp2}}
    return C

def construct_packing():
    # Paths
    sci_dir = first_existing(D_SCI_CAND)
    if not sci_dir:
        raise FileNotFoundError("Scientia n=26 path not found.")

    # Load packs
    exp = load_pack(D_EXP, D_EXP, centers_path=os.path.join(D_EXP, 'centers.txt'))
    noe_centers = first_existing([os.path.join(D_NOE, 'centers.txt'),
                                  'storage/noesis/latest_centers_sota243.txt',
                                  'storage/noesis/latest_centers.txt'])  # last resort
    noe = load_pack(D_NOE, D_NOE, centers_path=noe_centers if noe_centers else None)
    sci = load_pack(sci_dir, sci_dir, centers_path=os.path.join(sci_dir, 'centers.txt'))

    triad = {
      'exp_vs_noe': comp_pair(exp, noe, do_align=(noe['centers'] is not None)),
      'noe_vs_sci': comp_pair(noe, sci, do_align=(noe['centers'] is not None)),
      'exp_vs_sci': comp_pair(exp, sci, do_align=True),
      'meta': {'n': N, 'tol': TOL, 'noe_centers_path': noe_centers or 'None'}
    }

    os.makedirs(OUT_DIR, exist_ok=True)
    with open(OUT_JSON, 'w') as f:
        json.dump(triad, f, indent=2, sort_keys=True)

    # Flatten CSV
    rows=[]
    def add(name, res):
        rows.append([name, 'unaligned', 'boundary', res['unaligned']['boundary']['J'],
                     res['unaligned']['boundary']['I'], res['unaligned']['boundary']['U'], res['unaligned']['boundary']['D'],
                     res['meta']['A_norm']['bound_norm']['mode'], res['meta']['B_norm']['bound_norm']['mode']])
        rows.append([name, 'unaligned', 'pairs',    res['unaligned']['pairs']['J'],
                     res['unaligned']['pairs']['I'], res['unaligned']['pairs']['U'], res['unaligned']['pairs']['D'],
                     res['meta']['A_norm']['pairs_norm']['mode'], res['meta']['B_norm']['pairs_norm']['mode']])
        if 'aligned_A_to_B' in res:
            rows.append([name, 'aligned_A_to_B', 'boundary', res['aligned_A_to_B']['boundary']['J'],
                         res['aligned_A_to_B']['boundary']['I'], res['aligned_A_to_B']['boundary']['U'], res['aligned_A_to_B']['boundary']['D'],
                         res['meta']['A_norm']['bound_norm']['mode'], res['meta']['B_norm']['bound_norm']['mode']])
            rows.append([name, 'aligned_A_to_B', 'pairs',    res['aligned_A_to_B']['pairs']['J'],
                         res['aligned_A_to_B']['pairs']['I'], res['aligned_A_to_B']['pairs']['U'], res['aligned_A_to_B']['pairs']['D'],
                         res['meta']['A_norm']['pairs_norm']['mode'], res['meta']['B_norm']['pairs_norm']['mode']])

    add('exp_vs_noe', triad['exp_vs_noe'])
    add('noe_vs_sci', triad['noe_vs_sci'])
    add('exp_vs_sci', triad['exp_vs_sci'])

    with open(OUT_CSV, 'w', newline='') as f:
        w = csv.writer(f)
        w.writerow(['pair','mode','set','J','I','U','D','A_norm','B_norm'])
        for r in rows:
            w.writerow(r)

    # Return current packing unchanged
    c = np.loadtxt('storage/noesis/latest_centers.txt')
    r = np.loadtxt('storage/noesis/latest_radii.txt')
    return np.array(c, float).reshape(N,2), np.array(r, float).reshape(N,)
